#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: spike S8 (docs/cross-device-sync-design.md#comparing-the-three-by-hand).
# You create or sign in to four accounts and paste a few values. Secrets go to gitignored
# env files next to this script's folder and are never printed. Re-running keeps what is saved.
# ──────────────────────────────────────────────────────────────────────────

cd "$(dirname "${BASH_SOURCE[0]}")/.."   # spikes/sync-hosting

TOTAL_STAGES=5

banner "Sync hosting spike: accounts and keys"

# ── 1. Fly.io: runs the lean API and the Postgres candidate's API ─────────
stage "Fly.io: the two Node APIs"
ENV_FILE=".env.fly.local"
say "Fly runs two small always-on machines (lean and Postgres), about \$2-5 a month together."
say "Fly asks for a payment card before it will start any machine, even a tiny one."
note "Nothing secret is stored: flyctl keeps its own login in ~/.fly. Teardown deletes the apps."
if ! command -v fly >/dev/null 2>&1; then
  warn "flyctl is not installed."
  if command -v brew >/dev/null 2>&1 && confirm "Install it now with 'brew install flyctl'?"; then
    brew install flyctl
  else
    open_url "https://fly.io/docs/flyctl/install/"
    pause "Install flyctl, then press Enter"
  fi
fi
if ! fly auth whoami >/dev/null 2>&1; then
  step "A browser opens: sign in (or sign up) at Fly.io and add a card if asked."
  fly auth login
fi
say "Signed in as: $(fly auth whoami 2>/dev/null)"
note "Organizations you can use:"
fly orgs list 2>/dev/null | sed 's/^/    /' || true
ask FLY_ORG "Fly organization slug (usually 'personal'):"
write_env FLY_ORG "${FLY_ORG:-personal}"
note "Pick the region nearest you. It must be the same for both APIs. 'iad' is Ashburn, Virginia."
ask FLY_REGION "Fly region code [iad]:"
write_env FLY_REGION "${FLY_REGION:-iad}"
SUFFIX=$(_existing FLY_APP_SUFFIX || true)
if [[ -z "$SUFFIX" ]]; then SUFFIX=$(openssl rand -hex 3); fi
write_env FLY_APP_SUFFIX "$SUFFIX"
note "The apps will be named comp-sync-lean-$SUFFIX and comp-sync-pg-$SUFFIX."

# ── 2. Cloudflare R2: where the lean API's database replica lives ─────────
stage "Cloudflare R2: the lean database replica"
ENV_FILE=".env.r2.local"
say "Litestream copies the lean SQLite file to an R2 bucket. R2's free tier covers 10 GB."
say "R2 needs a payment method on the account even for the free tier."
open_url "https://dash.cloudflare.com/?to=/:account/r2/overview"
step "Sign in or sign up. In the left sidebar choose 'R2 Object Storage' and activate R2 if asked."
step "Copy your Account ID (R2 overview page, right-hand panel, or the hex part of your S3 API URL)."
ask R2_ACCOUNT_ID "Paste the Cloudflare account ID:"
write_env R2_ACCOUNT_ID "$R2_ACCOUNT_ID"
BUCKET_DEFAULT="composition-sync-spike-$SUFFIX"
step "Click 'Create bucket'. Name it exactly: $BUCKET_DEFAULT  (location: Automatic is fine)."
ask R2_BUCKET "Bucket name [$BUCKET_DEFAULT]:"
write_env R2_BUCKET "${R2_BUCKET:-$BUCKET_DEFAULT}"
step "Back on the R2 overview page open 'API' (or 'Manage API tokens'), then 'Create API token'."
step "Permission: Object Read & Write. Scope: only the bucket above. Create it."
step "Copy the Access Key ID and the Secret Access Key (shown once; use the S3-compatible pair, not the token value)."
ask_secret R2_ACCESS_KEY_ID "Paste the Access Key ID (hidden):"
ask_secret R2_SECRET_ACCESS_KEY "Paste the Secret Access Key (hidden):"
write_env R2_ACCESS_KEY_ID "$R2_ACCESS_KEY_ID"
write_env R2_SECRET_ACCESS_KEY "$R2_SECRET_ACCESS_KEY"

# ── 3. Neon: the managed Postgres candidate ────────────────────────────────
stage "Neon: managed Postgres"
ENV_FILE=".env.neon.local"
say "Neon's free plan is enough. Create the project in the same part of the world as Fly."
note "Fly 'iad' (Virginia) pairs with Neon 'AWS US East 1 (N. Virginia)' or 'US East 2 (Ohio)'."
open_url "https://console.neon.tech/app/projects"
step "Sign in or sign up, then 'New project'. Name: composition-sync-spike. Choose the region and the newest Postgres."
step "On the project dashboard click 'Connect'. Turn OFF 'Connection pooling' so you get the direct host."
step "Copy the connection string (it starts postgresql:// and ends ?sslmode=require)."
ask_secret NEON_DATABASE_URL "Paste the connection string (hidden):"
write_env NEON_DATABASE_URL "$NEON_DATABASE_URL"
say "Next two values let the scripts run the point-in-time restore drill and delete the project at the end."
step "Project settings -> General -> copy the Project ID (looks like 'quiet-river-123456')."
ask NEON_PROJECT_ID "Paste the Neon project ID:"
write_env NEON_PROJECT_ID "$NEON_PROJECT_ID"
open_url "https://console.neon.tech/app/settings/api-keys"
step "Account settings -> API keys -> 'Create new API key'. Name it composition-sync-spike. Copy it (shown once)."
ask_secret NEON_API_KEY "Paste the Neon API key (hidden):"
write_env NEON_API_KEY "$NEON_API_KEY"

# ── 4. Convex: the hosted-backend candidate ────────────────────────────────
stage "Convex: hosted backend"
ENV_FILE=".env.convex.local"
say "Convex needs no machine. The spike deploys its functions to a Production deployment."
note "I could not verify Convex's current dashboard wording, so adapt if a label differs."
open_url "https://dashboard.convex.dev"
step "Sign in or sign up. Create a project named composition-sync-spike. Pick the US East region to match Fly and Neon."
step "Make sure the project has a Production deployment (use the deployment switcher at the top of the dashboard)."
step "With Production selected open Settings -> 'URL & Deploy Key'."
step "Copy the 'Deployment URL' (ends .convex.cloud)."
ask CONVEX_URL "Paste the Deployment URL:"
write_env CONVEX_URL "${CONVEX_URL%/}"
step "Copy the HTTP Actions URL (ends .convex.site)."
ask CONVEX_SITE_URL "Paste the HTTP Actions URL:"
write_env CONVEX_SITE_URL "${CONVEX_SITE_URL%/}"
step "Click 'Generate Production Deploy Key' and copy it (it starts prod: and is shown once)."
ask_secret CONVEX_DEPLOY_KEY "Paste the deploy key (hidden):"
write_env CONVEX_DEPLOY_KEY "$CONVEX_DEPLOY_KEY"

# ── 5. Tokens and a check ──────────────────────────────────────────────────
stage "Dev tokens and a credentials check"
say "Generating the static per-device dev tokens (the spike has no real sign-in) ..."
node scripts/gen-tokens.ts
say "Checking each credential without printing it ..."
node scripts/check-credentials.ts || warn "something above failed: re-run this wizard and fix that stage"
note "Next: tell the Claude session that the wizard is done. It deploys all three candidates and runs the scenarios."
# ──────────────────────────────────────────────────────────────────────────

finish
